/* Generated from src/ui/fs-theme.css at configure time -- do not edit
 * this file; edit fs-theme.css and re-run CMake.
 *
 * The stylesheet is compiled into the binary so the installed program
 * needs no data files beside it (the installer stages the exe and the
 * GTK runtime, nothing else). */
#ifndef FS_THEME_CSS_H
#define FS_THEME_CSS_H

static const gchar fs_theme_css[] =
"/* =====================================================================\n * StockFW Light Theme (GTK3)\n *\n * Palette (1.0.7 redesign):\n *   canvas #F4F5F7     cards #FFFFFF, hairline #E3E6EB, radius 12\n *   sidebar #14161B    nav text #C9CED6, hover #1F232B, selected #2A2F39\n *   ink #16181D        muted #5B6472 (4.5:1 on white and on the canvas)\n *   primary button #16181D (white text)    links #1D4ED8\n *   selected row #EAF0FB (ink text): neutral, so it never reads as an\n *   alert -- red is kept for what is actually blocked or broken\n *   verdict: ok #1E7F4F on #F4FBF7, warn #8A5300 on #FFF8EB,\n *            bad #B42318 on #FEF4F3, unknown #3A4250 on #F6F7F9\n *\n * Only GTK3 properties are used; this file is compiled into the\n * binary at configure time (see fs-theme-css.h.in / CMakeLists.txt).\n * ===================================================================== */\n\n/* --- window & canvas ------------------------------------------------ */\nwindow {\n	background-color: #f4f5f7;\n}\n\n/* --- generic surfaces ----------------------------------------------- */\n/* A GtkFrame drawn as a card: white, hairline border, the title as a\n * heading inside it rather than a legend cut into the line (the pages\n * set the frame's own shadow to none). */\n.card-frame {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 12px;\n	padding: 4px 6px 6px 6px;\n	margin-bottom: 12px;\n}\nframe.card-frame > label {\n	margin: 10px 0 4px 6px;\n	padding: 0;\n	font-size: 13px;\n	font-weight: bold;\n	color: #16181d;\n}\n.content-area {\n	background-color: #f4f5f7;\n}\n\n/* --- buttons -------------------------------------------------------- */\n/* White face, fine grey border: secondary actions. */\n.btn-subtle {\n	background-image: none;\n	background-color: #ffffff;\n	border: 1px solid #cdd2da;\n	border-radius: 8px;\n	color: #16181d;\n	padding: 8px 16px;\n	font-weight: 600;\n	font-size: 13px;\n}\n.btn-subtle:hover {\n	background-color: #f4f5f7;\n	border-color: #aeb5c0;\n}\n.btn-subtle:checked {\n	background-color: #eef2f7;\n	border-color: #aeb5c0;\n}\n.btn-subtle:disabled {\n	background-color: #f4f5f7;\n	color: #8b93a1;\n	border-color: #e3e6eb;\n}\n\n/* The one main action on a screen. */\n.btn-primary {\n	background-color: #16181d;\n	background-image: none;\n	border: 1px solid #16181d;\n	border-radius: 8px;\n	color: #ffffff;\n	padding: 8px 16px;\n	font-weight: 600;\n	font-size: 13px;\n	box-shadow: none;\n}\n.btn-primary:hover {\n	background-color: #2a2f39;\n	border-color: #2a2f39;\n	box-shadow: none;\n}\n.btn-primary:active {\n	background-color: #000000;\n	box-shadow: none;\n}\n.btn-primary:disabled {\n	background-color: #c9ced6;\n	border-color: #c9ced6;\n	color: #f4f5f7;\n	box-shadow: none;\n}\n\n.btn-danger {\n	background-color: #ffffff;\n	background-image: none;\n	border: 1px solid #c62828;\n	border-radius: 4px;\n	color: #c62828;\n	padding: 6px 16px;\n	font-weight: bold;\n	font-size: 13px;\n}\n.btn-danger:hover {\n	background-color: #fdeaea;\n}\n\n/* The white sliver: Adwaita paints a 1px white inset highlight along\n * the top edge of a button in its hover / active / checked / focus\n * states.  This file never cleared box-shadow, so on every mouse-over\n * a thin white line appeared just inside the top border -- the \"bit of\n * white above any button\" (reproduced at y=1 in a pixel scan of a\n * hovered .btn-primary).  Our provider outranks the theme, so this one\n * state block removes the sliver for every button in the app -- tabs,\n * toolbar strips and dialogs included.  Keyboard focus stays visible\n * through the border/colour change that Adwaita keeps. */\nbutton:hover,\nbutton:active,\nbutton:checked,\nbutton:disabled,\nbutton:focus {\n	box-shadow: none;\n}\n\n/* Toolbar strip buttons. */\n.toolbar-button {\n	padding: 4px 8px;\n}\n\n/* --- entries & combos ------------------------------------------------ */\nentry,\n.entry,\nGtkSearchEntry {\n	background-color: #ffffff;\n	border: 1px solid #cdd2da;\n	border-radius: 8px;\n	color: #16181d;\n	padding: 6px 10px;\n	font-size: 13px;\n}\nentry:focus,\n.entry:focus,\nGtkSearchEntry:focus {\n	border-color: #1d4ed8;\n	background-color: #ffffff;\n}\n\n/* Drop-downs read as the white secondary buttons beside them. */\ncombobox button.combo {\n	background-image: none;\n	background-color: #ffffff;\n	border: 1px solid #cdd2da;\n	border-radius: 8px;\n	color: #16181d;\n	box-shadow: none;\n}\ncombobox button.combo:hover {\n	background-color: #f4f5f7;\n}\n\n/* --- dialog buttons --------------------------------------------------- *\n * Every dialog's button row (Cancel / OK, Cancel / Stage, Yes / No)\n * takes the page buttons' look: white secondary buttons, and the\n * dialog's default response -- the one Enter presses, which GTK marks\n * with .default -- in the dark primary colour of the sidebar.        */\n.dialog-action-area button {\n	background-image: none;\n	background-color: #ffffff;\n	border: 1px solid #cdd2da;\n	border-radius: 8px;\n	color: #16181d;\n	padding: 6px 14px;\n}\n.dialog-action-area button:hover {\n	background-color: #f4f5f7;\n}\n.dialog-action-area button.default {\n	background-color: #16181d;\n	border-color: #16181d;\n	color: #ffffff;\n}\n.dialog-action-area button.default:hover {\n	background-color: #2a2f39;\n	border-color: #2a2f39;\n}\n\n/* --- switches (profile toggles) -------------------------------------- */\nswitch {\n	background-color: #c9cdd2;\n	border: 1px solid #b8bdc3;\n	border-radius: 12px;\n	min-width: 46px;\n	min-height: 22px;\n}\nswitch:checked {\n	background-color: #1e7f4f;\n	border-color: #17643e;\n}\nswitch slider {\n	background-color: #ffffff;\n	border: 1px solid #aeb3b8;\n	border-radius: 10px;\n	min-width: 18px;\n	min-height: 18px;\n}\n/* Keyboard focus: GTK rings the slider, by default in a light grey\n * dash that all but vanishes on white.  The theme's focus blue,\n * solid, instead.  An outline is only drawn while focus is visible\n * (keyboard use), so a click shows nothing extra. */\nswitch:focus slider {\n	outline-color: #1d4ed8;\n	outline-style: solid;\n	outline-width: 2px;\n	outline-offset: -4px;\n}\n/* A switch that cannot act right now (Preferences: a block that needs\n * a device nobody chose) reads as faded, on or off. */\nswitch:disabled {\n	background-color: #e3e6eb;\n	border-color: #d5d9df;\n}\nswitch:checked:disabled {\n	background-color: #9cc7b0;\n	border-color: #8ab79f;\n}\nswitch:disabled slider {\n	border-color: #d5d9df;\n}\n\n/* --- data grids ------------------------------------------------------ *\n * Thin light-grey rules, grey header band with bold dark text, and a\n * white canvas.  Row striping: GtkTreeView has no per-row nth-child\n * matching that reaches the row area on every theme, so the store's\n * odd rows carry the .row-alt class from the cell renderer below.    */\n.data-grid,\ntreeview {\n	background-color: #ffffff;\n	color: #16181d;\n	font-size: 13px;\n	/* The UI font, as on the Overview.  Columns of addresses, ports\n	 * and digests set a fixed-width face on their own renderer, so\n	 * those still line up digit for digit. */\n}\n.data-grid header,\ntreeview header {\n	background-color: #ffffff;\n	border-bottom: 1px solid #e3e6eb;\n}\n.data-grid header button,\ntreeview header button {\n	background-color: #ffffff;\n	background-image: none;\n	color: #5b6472;\n	border: none;\n	border-radius: 0;\n	padding: 8px 10px;\n	font-weight: bold;\n	font-size: 12px;\n}\n.data-grid header button:hover,\ntreeview header button:hover {\n	background-color: #f4f5f7;\n}\n.data-grid row,\ntreeview row {\n	background-color: #ffffff;\n	color: #212121;\n}\n.data-grid row.row-alt,\ntreeview row.row-alt {\n	background-color: #f9f9f9;\n}\n/* Selection: a pale neutral blue with ink text.  It used to be the\n * accent red with white text, which made an ordinary selected row look\n * exactly like an alert. */\n.data-grid:selected,\ntreeview:selected,\n.data-grid row:selected,\ntreeview row:selected {\n	background-color: #eaf0fb;\n	color: #16181d;\n}\n/* Blocked rows: soft pastel alert tint, dark red text.  Painted by\n * the cell renderer (background + foreground columns), not by CSS,\n * so it survives selection and theme quirks. */\n.data-grid row.alert,\ntreeview row.alert {\n	background-color: #ffebee;\n	color: #b71c1c;\n}\n.data-grid row.alert:selected,\ntreeview row.alert:selected {\n	background-color: #f9d7d3;\n	color: #8a1c12;\n}\n\n/* --- Nexora AEGIS-ML & Card Polishing -------------------------------- */\n.nexora-card {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 12px;\n	padding: 14px;\n	margin-bottom: 12px;\n}\n\n.nexora-badge-ok {\n	background-color: #f4fbf7;\n	color: #1e7f4f;\n	border-radius: 6px;\n	padding: 4px 8px;\n	font-weight: 600;\n}\n\n.nexora-badge-warn {\n	background-color: #fff8eb;\n	color: #8a5300;\n	border-radius: 6px;\n	padding: 4px 8px;\n	font-weight: 600;\n}\n\n.nexora-badge-alert {\n	background-color: #fef4f3;\n	color: #b42318;\n	border-radius: 6px;\n	padding: 4px 8px;\n	font-weight: 600;\n}\n.data-grid row:selected,\ntreeview row:selected {\n	border: none;\n}\n/* In-cell text padding for compact network strings. */\n.data-grid cell,\ntreeview cell {\n	font-size: 13px;\n}\n\n/* --- status line (hero) ---------------------------------------------- */\n.hero-status {\n	background-color: #ffffff;\n	border: 1px solid #e0e0e0;\n	border-radius: 8px;\n	padding: 14px;\n	margin-bottom: 12px;\n}\n/* Circular badge around the state icon. */\n.hero-badge {\n	background-color: #78909c;\n	border-radius: 40px;\n	padding: 10px;\n}\n.hero-badge.badge-active {\n	background-color: #2e7d32;\n}\n.hero-badge.badge-stopped {\n	background-color: #c62828;\n}\n.hero-badge.badge-locked {\n	background-color: #b26a00;\n}\n.hero-badge.badge-unknown {\n	background-color: #78909c;\n}\n.hero-badge image {\n	color: #ffffff;\n}\n.state-active {\n	font-weight: bold;\n	color: #2e7d32;\n}\n.state-stopped {\n	font-weight: bold;\n	color: #c62828;\n}\n.state-locked {\n	font-weight: bold;\n	color: #b26a00;\n}\n.fs-counter {\n	font-weight: bold;\n	color: #212121;\n}\n.fs-counter-head {\n	font-weight: bold;\n	color: #424242;\n}\n.events-summary {\n	background-color: #ffffff;\n	border: 1px solid #e0e0e0;\n	border-radius: 8px;\n	padding: 8px;\n	margin-bottom: 12px;\n}\n/* Thin rules under each counter row, the summary's grid lines. */\n.events-summary label {\n	padding: 3px 8px;\n}\n.profile-row {\n	padding: 4px 0;\n}\n.profile-label {\n	font-size: 13px;\n	color: #212121;\n}\n\n/* --- headings & labels ----------------------------------------------- */\n.title-label {\n	font-weight: bold;\n	font-size: 16px;\n	color: #212121;\n}\n.heading-label {\n	font-weight: bold;\n	font-size: 14px;\n	color: #212121;\n}\n.dim-label {\n	color: #757575;\n	font-size: 12px;\n}\n\n/* --- reason strip on Events ------------------------------------------ */\n.warning-strip {\n	background-color: #fff8e1;\n	border: 1px solid #ffe082;\n	border-radius: 4px;\n	color: #b26a00;\n}\n.error-strip {\n	background-color: #ffebee;\n	border: 1px solid #ffcdd2;\n	border-radius: 4px;\n	color: #c62828;\n}\n\n/* --- Events sub-header utility bar ------------------------------------ */\n/* Sits on the page canvas above the list card, like the Overview's\n * controls; no strip of its own. */\n.events-toolbar {\n	background-color: transparent;\n	margin-bottom: 12px;\n}\n.events-count {\n	font-weight: bold;\n	font-size: 13px;\n	color: #212121;\n}\n\n/* --- read-only output panels (Copilot scrollback) --------------------- */\n.output-view {\n	background-color: #fafbfc;\n	border: 1px solid #e3e6eb;\n	border-radius: 8px;\n}\n.output-view textview,\n.output-view text {\n	background-color: #fafbfc;\n	color: #333333;\n	font-family: monospace;\n	font-size: 12px;\n}\n\n/* --- scrollbars ------------------------------------------------------ *\n * Deliberately NOT styled.  The flat-slider rules that were here made\n * GTK allocate a scrollbar slider a negative height (slider\n * min-height + margins exceeded what the trough handed out), which\n * showed up as gtk_widget_size_allocate warnings on every window\n * open.  The theme's own scrollbars are fine and the spec asks for\n * nothing more.                                                 */\n\n/* --- notebook (tabs are hidden; content on the canvas) --------------- */\nnotebook {\n	background-color: #f4f5f7;\n	border: none;\n}\n\n/* --- dialogs --------------------------------------------------------- */\ndialog {\n	background-color: #f4f5f7;\n}\n/* --- Activity page (1.0.6) ----------------------------------------- */\n/* Cards and stat tiles: the same white surface and hairline as the\n * Status page's hero card. */\n.chart-card,\n.stat-tile {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 12px;\n	padding: 14px 16px;\n	margin-bottom: 12px;\n}\n.card-title {\n	font-weight: bold;\n	font-size: 14px;\n	color: #212121;\n}\n/* The Overview's stat card wording: the name in quiet sentence case,\n * the number large in ink. */\n.stat-caption {\n	font-size: 13px;\n	color: #5b6472;\n}\n.stat-value {\n	font-weight: bold;\n	font-size: 26px;\n	color: #16181d;\n}\n.chart-legend {\n	color: #424242;\n	font-size: 12px;\n}\n\n/* Range picker: one segmented control, the selected range filled in\n * the app's accent like the selected tab. */\n.segmented button.seg-button {\n	background-image: none;\n	background-color: #ffffff;\n	border: 1px solid #c8cdd4;\n	border-radius: 0;\n	color: #424242;\n	padding: 4px 12px;\n	font-size: 13px;\n}\n.segmented button.seg-button:first-child {\n	border-radius: 6px 0 0 6px;\n}\n.segmented button.seg-button:last-child {\n	border-radius: 0 6px 6px 0;\n}\n.segmented button.seg-button:not(:first-child) {\n	border-left-width: 0;\n}\n.segmented button.seg-button:hover {\n	background-color: #f4f6f8;\n}\n.segmented button.seg-button:checked {\n	background-color: #16181d;\n	border-color: #16181d;\n	color: #ffffff;\n	font-weight: bold;\n}\n\n/* --- frame titles ---------------------------------------------------- */\n/* A frame's title sat flush on its border with no air on either side\n * (\"Network\", \"Active connections\", \"Selected file\", every Policy\n * group), reading as text struck through by the line.  A little\n * padding lifts it off the rule; weight and colour make it a heading. */\nframe > label {\n	margin-left: 8px;\n	padding: 0 4px;\n	font-weight: bold;\n	color: #424242;\n}\n\n/* Empty-state text over an empty list. */\n.empty-state {\n	color: #757575;\n	font-size: 13px;\n}\n\n/* =====================================================================\n * 1.0.7 redesign: sidebar and Overview\n * ===================================================================== */\n\n/* --- sidebar --------------------------------------------------------- */\n.fs-sidebar {\n	background-color: #14161b;\n	padding: 20px 12px 16px 12px;\n}\n.fs-brand {\n	padding: 0 8px 18px 8px;\n}\n/* The logo's dark lower half disappears on the sidebar; a light tile\n * gives it the background it was drawn for. */\n.fs-brand-tile {\n	background-color: #f4f5f7;\n	border-radius: 10px;\n}\n.fs-brand-name {\n	color: #ffffff;\n	font-weight: bold;\n	font-size: 15px;\n}\n.fs-brand-version {\n	color: #8b93a1;\n	font-size: 12px;\n}\n/* Every nav-item state shares one set of metrics; only colours change,\n * so selecting an item never moves anything (see the theme test). */\nbutton.nav-item {\n	background-image: none;\n	background-color: transparent;\n	border: none;\n	border-radius: 8px;\n	box-shadow: none;\n	text-shadow: none;\n	color: #c9ced6;\n	padding: 9px 10px;\n	min-height: 22px;\n	font-size: 14px;\n	font-weight: 500;\n	outline-color: #8b93a1;\n}\nbutton.nav-item:hover {\n	background-color: #1f232b;\n	color: #ffffff;\n}\nbutton.nav-item:active {\n	background-color: #262a33;\n	color: #ffffff;\n}\nbutton.nav-item:checked,\nbutton.nav-item:checked:hover,\nbutton.nav-item:checked:active,\nbutton.nav-item.nav-active,\nbutton.nav-item.nav-active:hover {\n	background-color: #2a2f39;\n	color: #ffffff;\n}\nbutton.nav-item label {\n	color: inherit;\n}\n.fs-sidebar-footer {\n	border-top: 1px solid #262a33;\n	margin-top: 10px;\n	padding: 14px 10px 0 10px;\n}\n.fs-side-state {\n	color: #ffffff;\n	font-weight: bold;\n	font-size: 13px;\n}\n.fs-side-backend {\n	color: #8b93a1;\n	font-size: 12px;\n}\n/* Status dots: drawn in their CSS colour. */\n.dot-ok      { color: #4ade80; }\n.dot-warn    { color: #fbbf24; }\n.dot-bad     { color: #e34948; }\n.dot-unknown { color: #8b93a1; }\n.recent-row .dot-bad { color: #e34948; }\n\n/* --- Overview: page ---------------------------------------------------- */\n.overview {\n	padding: 28px 32px 36px 32px;\n}\n/* Every page but the Overview: the shared header and the margins,\n * which match the Overview's so the title does not jump. */\n.page {\n	padding: 28px 32px 24px 32px;\n}\n.page-head {\n	margin-bottom: 18px;\n}\n/* A list in a card: a few pixels of inset keep the list's square\n * corners inside the card's rounded ones. */\n.list-card {\n	padding: 4px;\n}\n.card-heading.card-head {\n	padding: 14px 16px 8px 16px;\n}\n.page-title {\n	font-size: 22px;\n	font-weight: bold;\n	color: #16181d;\n}\n.page-subtitle,\n.muted {\n	color: #5b6472;\n	font-size: 13px;\n}\n.mono {\n	font-family: \"JetBrains Mono\", \"Cascadia Mono\", \"DejaVu Sans Mono\", monospace;\n	font-size: 12px;\n}\n.card {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 12px;\n	margin-bottom: 12px;\n}\n/* Soft lift for every card-like surface: one tight, faint shadow, so a\n * card reads as resting on the canvas without a heavy drop shadow. */\n.card,\n.card-frame,\n.chart-card,\n.stat-tile {\n	box-shadow: 0 1px 2px rgba(16, 24, 40, 0.06),\n	            0 1px 3px rgba(16, 24, 40, 0.04);\n}\n.padded-card {\n	padding: 16px;\n}\n.card-heading {\n	font-size: 13px;\n	font-weight: bold;\n	color: #16181d;\n}\n.card-head {\n	padding: 14px 16px 12px 16px;\n}\n.card-foot {\n	padding: 10px 16px 12px 16px;\n	border-top: 1px solid #eef0f3;\n}\n/* A flat button that reads as a link. */\nbutton.fs-link {\n	background-image: none;\n	background-color: transparent;\n	border: none;\n	box-shadow: none;\n	padding: 0 4px;\n	min-height: 0;\n	color: #1d4ed8;\n	font-size: 13px;\n}\nbutton.fs-link:hover {\n	color: #1e3a8a;\n	background-color: transparent;\n}\nbutton.fs-link label {\n	color: inherit;\n}\n\n/* --- Overview: verdict card ------------------------------------------- */\n.hero {\n	border: 1px solid #dadfe6;\n	border-radius: 12px;\n	padding: 24px;\n	background-color: #f6f7f9;\n	margin-bottom: 16px;\n}\n.hero-icon-tile {\n	border-radius: 14px;\n	background-color: #e8ebf0;\n}\n.hero-icon {\n	color: #5b6472;\n}\n.hero-title {\n	font-size: 20px;\n	font-weight: bold;\n	color: #16181d;\n}\n.hero-body {\n	font-size: 14px;\n	color: #3a4250;\n}\n.hero-tile {\n	background-color: #ffffff;\n	border: 1px solid #e1e5ea;\n	border-radius: 10px;\n	padding: 12px 14px;\n}\n.tile-caption {\n	color: #5b6472;\n	font-size: 12px;\n}\n.tile-value {\n	color: #16181d;\n	font-size: 14px;\n	font-weight: bold;\n}\n.tile-value.good { color: #1e7f4f; }\n.tile-value.warn { color: #8a5300; }\n.tile-value.bad  { color: #b42318; }\n\n.hero.level-ok {\n	background-color: #f4fbf7;\n	border-color: #bfe3cf;\n}\n.hero.level-ok .hero-icon-tile { background-color: #ddf2e6; }\n.hero.level-ok .hero-icon      { color: #1e7f4f; }\n.hero.level-ok .hero-title     { color: #145a38; }\n.hero.level-ok .hero-body      { color: #2f4f3e; }\n.hero.level-ok .hero-tile      { border-color: #cfe8da; }\n\n.hero.level-warn {\n	background-color: #fff8eb;\n	border-color: #f3d9a4;\n}\n.hero.level-warn .hero-icon-tile { background-color: #fcebc8; }\n.hero.level-warn .hero-icon      { color: #a15c00; }\n.hero.level-warn .hero-title     { color: #6b3f00; }\n.hero.level-warn .hero-body      { color: #4f3a12; }\n.hero.level-warn .hero-tile      { border-color: #f1ddb0; }\n\n.hero.level-bad {\n	background-color: #fef4f3;\n	border-color: #f4c7c3;\n}\n.hero.level-bad .hero-icon-tile { background-color: #fbe1de; }\n.hero.level-bad .hero-icon      { color: #b42318; }\n.hero.level-bad .hero-title     { color: #8a1c12; }\n.hero.level-bad .hero-body      { color: #5f2a26; }\n.hero.level-bad .hero-tile      { border-color: #f2d0cc; }\n\n/* --- Overview: totals, lists ------------------------------------------- */\n.stat-card {\n	padding: 16px 18px;\n}\n.stat-big {\n	font-size: 26px;\n	font-weight: bold;\n	color: #16181d;\n}\n.stat-note {\n	color: #5b6472;\n	font-size: 12px;\n}\n.overview-grid {\n	font-family: inherit;\n	font-size: 13px;\n}\n.overview-grid header button {\n	background-color: #ffffff;\n	border: none;\n	border-bottom: 1px solid #e3e6eb;\n	color: #5b6472;\n	font-size: 12px;\n	padding: 8px 10px;\n}\n.adapter-tile {\n	background-color: #eef2f7;\n	border-radius: 9px;\n	color: #334155;\n}\n.adapter-name {\n	font-size: 14px;\n	color: #16181d;\n}\n.adapter-num {\n	font-size: 12px;\n	color: #16181d;\n}\n.adapter-num-muted {\n	font-size: 12px;\n	color: #5b6472;\n}\n.recent-row {\n	padding: 10px 0;\n	border-bottom: 1px solid #eef0f3;\n}\n.recent-title {\n	font-size: 13px;\n	font-weight: bold;\n	color: #16181d;\n}\n.recent-detail {\n	font-size: 12px;\n	color: #5b6472;\n}\n.card-frame .profile-row {\n	padding: 10px 14px;\n}\n/* \"In use\": the profile protecting a connected network right now.  The\n * selection tint, so it reads as \"this one\", not as a warning. */\n.in-use {\n	font-size: 12px;\n	font-weight: bold;\n	color: #16181d;\n	background-color: #eaf0fb;\n	border-radius: 10px;\n	padding: 2px 10px;\n	margin-right: 10px;\n}\n.card-head entry {\n	min-height: 28px;\n	padding-top: 2px;\n	padding-bottom: 2px;\n}\n\n/* =====================================================================\n * Copilot page (1.0.7): findings, policy health, changes.\n * Light, as the rest of the app is, whatever the desktop theme: a dark\n * page inside the light window read as a rendering fault.\n * ===================================================================== */\n.cp-title {\n	font-size: 13px;\n	font-weight: bold;\n	color: #16181d;\n}\n.cp-sub,\n.cp-body {\n	font-size: 13px;\n	color: #3a4250;\n}\n.cp-meta,\n.cp-caption {\n	font-size: 12px;\n	color: #5b6472;\n}\n/* The evidence cells carry only .mono; without a colour of their own\n * they took the desktop theme's text colour, white under a dark theme,\n * on the white card. */\n#cp-evidence label.mono {\n	color: #16181d;\n}\n.cp-drawer-head {\n	font-size: 12px;\n	font-weight: bold;\n	color: #16181d;\n	margin-top: 4px;\n}\n.cp-arrow {\n	color: #5b6472;\n	font-size: 12px;\n}\n.cp-drawer {\n	padding: 8px 0 4px 0;\n	border-top: 1px solid #eef0f3;\n	margin-top: 6px;\n}\n.cp-list-frame {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 10px;\n	margin-bottom: 12px;\n}\n.cp-list-frame > border {\n	border: none;\n}\nlist.cp-list {\n	background-color: transparent;\n}\nlist.cp-list row.cp-row {\n	padding: 10px 12px;\n	border-bottom: 1px solid #eef0f3;\n	background-color: transparent;\n}\nlist.cp-list row.cp-row:last-child {\n	border-bottom: none;\n}\nlist.cp-list row.cp-row:hover {\n	background-color: #f7f8fa;\n}\nlist.cp-list row.cp-row:focus {\n	outline: 2px solid #1d4ed8;\n	outline-offset: -2px;\n}\n.cp-pill {\n	padding: 2px 8px;\n}\n.cp-strip {\n	padding: 8px 12px;\n	font-size: 13px;\n}\n.ok-strip {\n	background-color: #f4fbf7;\n	border: 1px solid #bfe3cf;\n	border-radius: 4px;\n	color: #145a38;\n}\n/* The What-If log's tones (its text tags read these colours). */\n.output-view textview.tone-ok   { color: #1e7f4f; }\n.output-view textview.tone-bad  { color: #b42318; }\n.output-view textview.tone-warn { color: #8a5300; }\n.output-view textview.tone-info { color: #1d4ed8; }\n.output-view textview.tone-dim  { color: #5b6472; }\n\n/* =====================================================================\n * 1.0.7: the sidebar Help and Preferences share\n * One width (FS_SIDE_WIDTH), the same group headings, and items of the\n * same size, icon and inset, so the two windows match side by side.\n * Help's items are list rows, Preferences' toggle buttons; the rules\n * below give both the same box.\n * ===================================================================== */\n.side-nav {\n	padding: 18px 10px 12px 10px;\n}\n.side-nav .fs-brand {\n	padding: 0 14px 12px 14px;\n}\nlabel.side-section {\n	color: #a9b0bc;\n	font-size: 11px;\n	font-weight: bold;\n	padding: 14px 14px 4px 14px;\n}\nbutton.nav-item.side-item {\n	margin: 1px 4px;\n	padding: 7px 10px;\n	min-height: 0;\n	font-size: 13px;\n}\n/* The dot beside a Preferences page with unsaved changes. */\n.nav-changed-dot {\n	color: #fbbf24;\n}\n\n/* =====================================================================\n * 1.0.7: the Preferences window (src/ui/fs-prefsdialog.c)\n * A centred column: each page its icon, title and a line on what it is\n * for, then groups of settings, a small heading over a white card.\n * Each setting a row with its name, one line on what it does and the\n * control on the right; a changed row carries a blue bar on its left.\n * ===================================================================== */\n.pref-page-head {\n	margin-bottom: 14px;\n}\n.pref-page-icon {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 12px;\n	padding: 10px;\n	color: #16181d;\n}\n.pref-group {\n	margin-top: 10px;\n}\nlabel.pref-group-title {\n	font-size: 12px;\n	font-weight: bold;\n	color: #5b6472;\n	padding: 0 4px 8px 4px;\n}\n.pref-card {\n	padding: 2px 0;\n	margin-bottom: 12px;\n}\n.pref-row {\n	padding: 12px 18px;\n	border-top: 1px solid #eef0f3;\n}\n/* No rule above a card's first row. */\n.pref-card > .pref-row:first-child {\n	border-top-width: 0;\n}\n.pref-row.pref-changed {\n	box-shadow: inset 3px 0 0 #1d4ed8;\n}\n.pref-label {\n	font-size: 13px;\n	font-weight: bold;\n	color: #16181d;\n}\n/* Why a row cannot act right now: amber text, readable on white. */\n.pref-reason {\n	font-size: 12px;\n	color: #8a5300;\n}\n/* A consequence worth stopping for (restrictive outbound). */\n.pref-warning {\n	background-color: #fff8eb;\n	border: 1px solid #f3d9a4;\n	border-radius: 8px;\n	color: #6b3f00;\n	font-size: 12px;\n	padding: 10px 12px;\n	margin: 2px 18px 12px 18px;\n}\n/* A Save that the system refused (start at sign-in): a deep red on a\n * pale red, 5.8:1. */\n.pref-error {\n	background-color: #fdeeee;\n	border: 1px solid #f2c4c4;\n	border-radius: 8px;\n	color: #b3261e;\n	font-size: 12px;\n	padding: 10px 12px;\n	margin: 2px 18px 12px 18px;\n}\n.pref-note {\n	color: #5b6472;\n	font-size: 12px;\n	padding: 8px 18px 10px 18px;\n	border-top: 1px solid #eef0f3;\n}\n.state-pill {\n	font-size: 12px;\n	font-weight: bold;\n	color: #3a4250;\n	background-color: #eef2f7;\n	border-radius: 10px;\n	padding: 2px 12px;\n}\n.state-pill.on {\n	color: #8a5300;\n	background-color: #fff8eb;\n}\n.prefs-footer {\n	background-color: #ffffff;\n	border-top: 1px solid #e3e6eb;\n	padding: 12px 24px;\n}\n/* What Save will write: grey with nothing to save, amber with. */\nlabel.prefs-status {\n	font-size: 12px;\n	font-weight: bold;\n	color: #3a4250;\n	background-color: #eef2f7;\n	border-radius: 10px;\n	padding: 3px 12px;\n}\nlabel.prefs-status.pending {\n	color: #6b3f00;\n	background-color: #fff8eb;\n}\n\n/* =====================================================================\n * 1.0.7: Help (src/ui/fs-helpwindow.c) and About (fs-aboutdialog.c)\n * The Preferences window's sidebar and page.  Every label, link, entry\n * and surface below names its colour, so a dark desktop theme\n * (Adwaita:dark) cannot put its light text on these light pages; the\n * help smoke measures the contrast of every label under it.\n *   body text #2B303A on white    links #1D4ED8\n *   note #1E3A8A on #EEF4FF    warning #6B3F00 on #FFF8EB\n *   not in this build #3A4250 on white, dashed border\n * ===================================================================== */\n.help-nav scrolledwindow,\n.help-nav viewport {\n	background-color: #14161b;\n	border: none;\n}\nentry.help-search {\n	background-color: #1f232b;\n	background-image: none;\n	color: #ffffff;\n	caret-color: #ffffff;\n	border: 1px solid #343a46;\n	border-radius: 8px;\n	box-shadow: none;\n	margin: 0 4px 8px 4px;\n	min-height: 30px;\n}\nentry.help-search:focus {\n	border-color: #8b93a1;\n}\nentry.help-search image {\n	color: #a9b0bc;\n}\nentry.help-search selection {\n	background-color: #3b4a6b;\n	color: #ffffff;\n}\nlist.help-topics {\n	background-color: #14161b;\n	color: #c9ced6;\n}\nlist.help-topics row {\n	background-color: transparent;\n	background-image: none;\n	border-radius: 8px;\n	padding: 7px 10px;\n	margin: 1px 4px;\n	min-height: 0;\n	color: #c9ced6;\n	outline-color: #8b93a1;\n}\nlist.help-topics row label {\n	color: #c9ced6;\n	font-size: 13px;\n}\n/* A subtopic's words line up with its parent's, after the icon. */\nlist.help-topics row.help-subtopic {\n	padding-left: 36px;\n}\nlist.help-topics row.help-subtopic label {\n	font-size: 12px;\n}\nlist.help-topics row:hover {\n	background-color: #1f232b;\n}\nlist.help-topics row:hover label {\n	color: #ffffff;\n}\n/* The topic shown: marked, not selected (the list has no selection,\n * so moving keyboard focus along it opens nothing). */\nlist.help-topics row.help-current,\nlist.help-topics row.help-current:hover {\n	background-color: #2a2f39;\n}\nlist.help-topics row.help-current label {\n	color: #ffffff;\n	font-weight: bold;\n}\nlabel.help-empty {\n	color: #a9b0bc;\n	font-size: 12px;\n	padding: 8px 14px;\n}\n\n/* --- the page --- */\n.help-content {\n	background-color: #f4f5f7;\n}\n.help-toolbar {\n	padding: 12px 24px 0 24px;\n}\nbutton.help-history {\n	padding: 4px 8px;\n	min-height: 0;\n	min-width: 0;\n}\nlabel.help-crumb-sep {\n	font-size: 13px;\n	color: #5b6472;\n}\n.help-content scrolledwindow,\n.help-content viewport {\n	background-color: #f4f5f7;\n	border: none;\n}\n.help-page {\n	padding: 8px 40px 40px 40px;\n}\n.help-head {\n	padding-bottom: 14px;\n	margin-bottom: 18px;\n	border-bottom: 1px solid #e3e6eb;\n}\nlabel.help-title {\n	font-size: 24px;\n	font-weight: bold;\n	color: #16181d;\n}\nlabel.help-summary {\n	font-size: 14px;\n	color: #5b6472;\n}\n.help-article label {\n	color: #2b303a;\n}\nlabel.help-para {\n	font-size: 14px;\n	color: #2b303a;\n}\nlabel.help-h2 {\n	font-size: 16px;\n	font-weight: bold;\n	color: #16181d;\n	margin-top: 14px;\n}\n.help-article label.help-h3 {\n	font-size: 12px;\n	font-weight: bold;\n	color: #5b6472;\n}\n.help-content label link:link {\n	color: #1d4ed8;\n}\n.help-content label link:visited {\n	color: #5b21b6;\n}\n.help-content label link:hover {\n	color: #1e3a8a;\n}\n.help-content label selection {\n	background-color: #cfdcf7;\n	color: #16181d;\n}\n.help-article label.help-step-num {\n	background-color: #16181d;\n	color: #ffffff;\n	border-radius: 11px;\n	min-width: 22px;\n	min-height: 22px;\n	font-size: 12px;\n	font-weight: bold;\n	padding: 0;\n	margin-top: 1px;\n}\n.help-article label.help-bullet {\n	color: #5b6472;\n	font-size: 14px;\n	min-width: 12px;\n	padding-left: 6px;\n}\n.help-callout {\n	border-radius: 10px;\n	border: 1px solid #c7d7fe;\n	background-color: #eef4ff;\n	padding: 12px 14px;\n}\n.help-callout label.help-callout-title {\n	font-size: 12px;\n	font-weight: bold;\n}\n.help-callout label.help-callout-text {\n	font-size: 13px;\n}\n.help-article .help-note label,\n.help-note .help-callout-icon {\n	color: #1e3a8a;\n}\n.help-warn {\n	background-color: #fff8eb;\n	border-color: #f3d9a4;\n}\n.help-article .help-warn label,\n.help-warn .help-callout-icon,\n.help-content .help-warn label link:link {\n	color: #6b3f00;\n}\n.help-soon {\n	background-color: #ffffff;\n	border-color: #b8c0cc;\n	border-style: dashed;\n}\n.help-article .help-soon label,\n.help-soon .help-callout-icon {\n	color: #3a4250;\n}\n.help-keys-row {\n	padding: 2px 0;\n}\n.help-article label.help-key {\n	background-color: #ffffff;\n	color: #16181d;\n	border: 1px solid #cfd4dc;\n	border-bottom-width: 2px;\n	border-radius: 6px;\n	padding: 1px 8px;\n	font-family: \"JetBrains Mono\", \"Cascadia Mono\", \"DejaVu Sans Mono\", monospace;\n	font-size: 12px;\n}\n.help-article label.help-key-plus {\n	color: #5b6472;\n	font-size: 12px;\n}\n.help-code {\n	background-color: #16181d;\n	border-radius: 8px;\n	padding: 10px 14px;\n}\n.help-article label.help-code-text {\n	color: #e8ebf0;\n	font-family: \"JetBrains Mono\", \"Cascadia Mono\", \"DejaVu Sans Mono\", monospace;\n	font-size: 12px;\n}\n.help-article label.help-code-text selection {\n	background-color: #3b4a6b;\n	color: #ffffff;\n}\n.help-related {\n	margin-top: 16px;\n	padding-top: 14px;\n	border-top: 1px solid #e3e6eb;\n}\nbutton.help-chip {\n	background-color: #ffffff;\n	background-image: none;\n	border: 1px solid #dadfe6;\n	border-radius: 14px;\n	box-shadow: none;\n	color: #16181d;\n	padding: 3px 12px;\n	min-height: 0;\n	font-size: 12px;\n}\n.help-article button.help-chip label {\n	color: #16181d;\n}\nbutton.help-chip:hover {\n	background-color: #eaf0fb;\n	border-color: #c7d7fe;\n}\n.help-children {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 12px;\n	padding: 14px 16px 6px 16px;\n	margin-bottom: 12px;\n}\n.help-child {\n	padding: 8px 0;\n	border-top: 1px solid #eef0f3;\n}\n.help-children > .help-child:nth-child(2) {\n	border-top-width: 0;\n}\nbutton.help-child-link {\n	background-image: none;\n	background-color: transparent;\n	border: none;\n	box-shadow: none;\n	padding: 0;\n	min-height: 0;\n}\n.help-article button.help-child-link label {\n	color: #1d4ed8;\n	font-weight: bold;\n	font-size: 14px;\n}\n.help-article label.help-child-summary {\n	color: #5b6472;\n	font-size: 13px;\n}\nbutton.help-next {\n	margin-top: 18px;\n}\n.help-article button.help-next label {\n	color: #1d4ed8;\n	font-size: 14px;\n	font-weight: bold;\n}\n.help-content button.fs-link label {\n	color: #1d4ed8;\n}\n\n/* --- About --- */\ndialog.about-window,\ndialog.about-window > box {\n	background-color: #f4f5f7;\n}\n.about-body {\n	padding: 24px 24px 16px 24px;\n}\n.about-logo-tile {\n	background-color: #ffffff;\n	border: 1px solid #e3e6eb;\n	border-radius: 18px;\n	padding: 10px;\n}\nlabel.about-name {\n	font-size: 24px;\n	font-weight: bold;\n	color: #16181d;\n}\nlabel.about-version {\n	font-size: 13px;\n	color: #5b6472;\n}\nlabel.about-desc {\n	font-size: 14px;\n	color: #2b303a;\n}\n.about-card {\n	padding: 14px 16px;\n	margin-bottom: 12px;\n}\nlabel.about-credit,\nlabel.about-text {\n	font-size: 13px;\n	color: #2b303a;\n}\nbutton.about-link {\n	background-image: none;\n	background-color: transparent;\n	border: none;\n	box-shadow: none;\n	padding: 0 2px;\n}\nbutton.about-link label {\n	color: #1d4ed8;\n	font-size: 13px;\n}\n.about-footer {\n	background-color: #ffffff;\n	border-top: 1px solid #e3e6eb;\n	padding: 12px 24px;\n}\nlabel.about-copied {\n	color: #1e7f4f;\n	font-size: 12px;\n	font-weight: bold;\n}\n.about-window button.btn-subtle label,\n.prefs-footer button.btn-subtle label {\n	color: inherit;\n}\nwindow#fs-licence,\n.licence-body {\n	background-color: #f4f5f7;\n}\n.licence-body {\n	padding: 16px;\n}\ntextview.licence-text,\ntextview.licence-text text {\n	background-color: #ffffff;\n	color: #16181d;\n}\ntextview.licence-text text selection {\n	background-color: #cfdcf7;\n	color: #16181d;\n}\n.licence-scroll {\n	border: 1px solid #e3e6eb;\n	background-color: #ffffff;\n}\n.licence-body label.about-text {\n	color: #2b303a;\n}\n.licence-switcher button {\n	background-color: #ffffff;\n	background-image: none;\n	border: 1px solid #dadfe6;\n	box-shadow: none;\n	color: #16181d;\n	padding: 4px 14px;\n}\n.licence-switcher button label {\n	color: #16181d;\n}\n.licence-switcher button:checked {\n	background-color: #16181d;\n	border-color: #16181d;\n}\n.licence-switcher button:checked label {\n	color: #ffffff;\n}\n";

#endif /* FS_THEME_CSS_H */
